quotes.text:
& .config-option {
  background-color: color-mix(in srgb, var(--color-surface-base) 50%, transparent);
  display: flex;
  flex-direction: column;
  border-radius: 10px;
  cursor: pointer;
  overflow: hidden;
  font-size: 1.2rem;
  line-height: normal;
  border: 1px solid transparent;

  & .badge:not(.experimental) {
    display: none;
  }

  &.recommended-protocol .badge:not(.experimental) {
    display: initial;
  }

  & .config-title {
    color: light-dark(var(--color-primary-default), #feffff);
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    padding-block: var(--hub-config-option-padding-block) 2px;
    padding-inline: var(--hub-config-option-padding-inline);
    font-weight: bold;

    & .config-title-text {
      flex: 1;
      line-height: 1;
    }
